# Build libodb, libodb-sqlite, and libcommon, then build and run the test
# drivers using the code generated by run_tests.py (out/<name>/).
#
import os, re, sys, glob, subprocess, concurrent.futures as cf

S = os.path.dirname(os.path.abspath(__file__))
ROOT = os.environ.get('ROOT', os.path.normpath(os.path.join(S, '..', '..', '..')))
TESTS = os.path.join(ROOT, 'odb-tests')
INC = os.path.join(S, 'inc')
OUT = os.path.join(os.environ.get('WORK', os.getcwd()), os.environ.get('OUTDIR', 'out'))
LIBS = os.path.join(os.environ.get('WORK', os.getcwd()), 'libs')
GXX = os.environ.get('GXX', 'g++')
AR = os.environ.get('AR', 'ar')

ONLY = sys.argv[1:]

DEFS = ['-DLIBODB_STATIC', '-DLIBODB_SQLITE_STATIC', '-DLIBCOMMON_STATIC',
        '-DDATABASE_SQLITE']
INCS = ['-I' + INC, '-I' + os.path.join(ROOT, 'libodb'),
        '-I' + os.path.join(ROOT, 'libodb-sqlite'), '-I' + TESTS]

def sh(cmd, cwd=None):
    p = subprocess.run(cmd, capture_output=True, text=True, cwd=cwd)
    return p.returncode, p.stdout + p.stderr

def build_libs():
    os.makedirs(LIBS, exist_ok=True)
    lib = os.path.join(LIBS, 'libtest.a')
    if os.path.exists(lib):
        return lib
    srcs = []
    for f in glob.glob(os.path.join(ROOT, 'libodb', 'odb', '*.cxx')):
        srcs.append((f, ['-DLIBODB_STATIC_BUILD']))
    for f in glob.glob(os.path.join(ROOT, 'libodb', 'odb', 'details', '*.cxx')):
        if os.path.basename(f) not in ('condition.cxx', 'lock.cxx', 'mutex.cxx'):
            srcs.append((f, ['-DLIBODB_STATIC_BUILD']))
    pg = os.path.join(ROOT, 'libodb-sqlite', 'odb', 'sqlite', 'details',
                      'pregenerated')
    for f in glob.glob(os.path.join(ROOT, 'libodb-sqlite', 'odb', 'sqlite',
                                    '**', '*.cxx'), recursive=True):
        srcs.append((f, ['-I' + pg, '-DLIBODB_SQLITE_STATIC_BUILD']))
    srcs.append((os.path.join(TESTS, 'libcommon', 'common.cxx'),
                 ['-DLIBCOMMON_STATIC_BUILD']))

    def comp(a):
        i, (f, extra) = a
        o = os.path.join(LIBS, '%03d.o' % i)
        r, out = sh([GXX, '-std=c++17', '-O1', '-w', '-c', f, '-o', o] +
                    extra + DEFS + INCS)
        if r != 0:
            print('lib compile failed:', f, out[:2000])
            sys.exit(1)
        return o

    with cf.ThreadPoolExecutor(8) as ex:
        objs = list(ex.map(comp, enumerate(srcs)))
    r, out = sh([AR, 'rcs', lib] + objs)
    assert r == 0, out
    return lib

def run(a):
    d, lib = a
    name = os.path.relpath(d, TESTS).replace('\\', '/')
    out = os.path.join(OUT, name)
    drv = os.path.join(d, 'driver.cxx')
    if not os.path.exists(drv) or not os.path.isdir(out):
        return None
    gen = glob.glob(os.path.join(out, '*-odb*.cxx'))
    if not gen:
        return (name, 'nogen', '')
    bf = open(os.path.join(d, 'buildfile'), encoding='utf-8').read()
    std = 'c++17' if re.search(r'--std\s+(\(\$cplusplus[^)]*\)|c\+\+17)', bf) else 'c++11'
    # Other sources in the test directory (besides the driver and headers).
    extra = [f for f in glob.glob(os.path.join(d, '*.cxx'))
             if os.path.basename(f) != 'driver.cxx']
    exe = os.path.join(out, 'driver.exe')
    r, o = sh([GXX, '-std=' + std, '-O0', '-w', '-o', exe, drv] + extra +
              gen + DEFS + ['-I' + out, '-I' + d, '-I' + OUT, '-I' + os.path.join(OUT, 'common'), '-I' + os.path.join(TESTS, 'common')] + INCS +
              [lib, '-lsqlite3', '-pthread', '-static'])
    if r != 0:
        return (name, 'build', o[:3000])
    db = os.path.join(out, 'odb-test.db')
    if os.path.exists(db):
        os.remove(db)
    try:
        p = subprocess.run([exe, '--database', db], capture_output=True,
                           text=True, cwd=out, timeout=120)
    except subprocess.TimeoutExpired:
        return (name, 'timeout', '')
    if p.returncode != 0:
        return (name, 'run', (p.stdout + p.stderr)[-3000:])
    return (name, 'ok', '')

lib = build_libs()
dirs = []
for grp in ['common', 'sqlite']:
    for r, ds, fs in os.walk(os.path.join(TESTS, grp)):
        ds.sort()
        if 'driver.cxx' in fs:
            if ONLY and not any(o in r for o in ONLY):
                continue
            dirs.append(r)

print(len(dirs), lib); cnt = {}
with cf.ThreadPoolExecutor(8) as ex:
    for res in ex.map(run, [(d, lib) for d in dirs]):
        if res is None:
            continue
        name, st, msg = res
        cnt[st] = cnt.get(st, 0) + 1
        if st != 'ok':
            print('=== %s %s' % (st, name))
            print(msg)
print(cnt)
sys.exit(0 if cnt and set(cnt) == {'ok'} else 1)
